

`timescale 1ns / 10ps

module test_serial ;

integer _failed ;
reg v_XNTrst;
reg v_XTck;
reg v_XTms;
reg v_XTdi;
reg v_XMclk;
reg[0:0] e_out5, m_out5;
event _check_out5 ;
wire[0:0] r_out5;

wire XNTrst, XTck, XTms, XTdi, XTdo, XMclk ;

assign {XMclk} = v_XMclk;
assign {XNTrst} = v_XNTrst;
assign {XTck} = v_XTck;
assign {XTms} = v_XTms;
assign {XTdi} = v_XTdi;
assign r_out5 = {XTdo};

always @(_check_out5) begin
if((e_out5&m_out5) !== (r_out5&m_out5)) begin
    $write($time, ": Incorrect response (%b, expected %b) :: TDO \n", r_out5, e_out5);
    _failed = _failed + 1;
    end
end

ARM7TDMIr3 u_proc (
      .MCLK    (XMclk),
      .nRESET  (1'b1),
      .TBE     (1'b0),   // ale, arm, debug, mul, pipe, regnew, thumb
  //  .TBE     (1'b1),   // ice
      .nTRST   (XNTrst),
      .TCK     (XTck),
      .TDI     (XTdi),
      .TDO     (XTdo),
      .TMS     (XTms) );

